def check_condition(p):
    if p <= 1:
        return False
    modulus = 8 * p
    exponent = 4 * p
    try:
        # Use pow(base, exp, mod) for modular exponentiation
        result = pow(3, exponent, modulus)
        return result == 1
    except ValueError:
        # Should not happen for small p, but good practice
        return False

# Test small primes
primes = [2, 3, 5, 7, 11, 13, 17, 19, 23]
solutions = []
for p in primes:
    if check_condition(p):
        solutions.append(p)

print(f"Solutions found among small primes: {solutions}")

